{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-8DDuIi/src/simulate.js","content":"/**
 * Parses a limiter file and replays it, producing either the per-event
 * verdict log (`replay`) or the per-key totals (`summary`). Parsing and
 * simulation happen in a single pass over the lines, since every error the
 * spec describes can be detected without looking ahead.
 */
import { LineError } from './errors.js'
import { TokenBucket, SlidingWindow } from './policies.js'

const NAME_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function checkName(word, line, kind, label) {
  if (!NAME_RE.test(word)) throw new LineError(line, `invalid ${kind} ${word}`)
  return word
  void label
}

function parseCount(word, line, field, least) {
  if (!INT_RE.test(word) || BigInt(word) < least) {
    throw new LineError(line, `${field} must be an integer of at least ${least}`)
  }
  return BigInt(word)
}

export function simulate(text, mode) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = new Map()
  let eventsStarted = false
  let lastTick = null

  const out = []
  const stats = new Map()
  let totalAllowed = 0
  let totalDenied = 0

  function statsFor(key) {
    let s = stats.get(key)
    if (s === undefined) {
      s = { allowed: 0, denied: 0 }
      stats.set(key, s)
    }
    return s
  }

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const raw = lines[i].trim()
    if (raw === '' || raw.startsWith('#')) continue
    const tokens = raw.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (eventsStarted) {
        throw new LineError(lineNo, 'declarations must come before the first event')
      }
    } else if (directive !== 'event') {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) {
        throw new LineError(lineNo, 'expected bucket <name> <capacity> <refill> <per>')
      }
      const [, name, capacityWord, refillWord, perWord] = tokens
      checkName(name, lineNo, 'policy name')
      const capacity = parseCount(capacityWord, lineNo, 'capacity', 1n)
      const refill = parseCount(refillWord, lineNo, 'refill', 0n)
      const per = parseCount(perWord, lineNo, 'per', 1n)
      if (policies.has(name)) throw new LineError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new TokenBucket(capacity, refill, per))
    } else if (directive === 'window') {
      if (tokens.length !== 4) {
        throw new LineError(lineNo, 'expected window <name> <limit> <span>')
      }
      const [, name, limitWord, spanWord] = tokens
      checkName(name, lineNo, 'policy name')
      const limit = parseCount(limitWord, lineNo, 'limit', 0n)
      const span = parseCount(spanWord, lineNo, 'span', 1n)
      if (policies.has(name)) throw new LineError(lineNo, `policy ${name} is declared twice`)
      policies.set(name, new SlidingWindow(limit, span))
    } else if (directive === 'route') {
      if (tokens.length < 3) {
        throw new LineError(lineNo, 'expected route <prefix> <policy>...')
      }
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(prefix, lineNo, 'route prefix')
      for (const name of policyNames) {
        if (!policies.has(name)) throw new LineError(lineNo, `unknown policy ${name}`)
      }
      if (routes.has(prefix)) throw new LineError(lineNo, `prefix ${prefix} is routed twice`)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (tokens.length !== 3) {
        throw new LineError(lineNo, 'expected event <tick> <key>')
      }
      eventsStarted = true
      const [, tickWord, key] = tokens
      const tick = parseCount(tickWord, lineNo, 'tick', 0n)
      checkName(key, lineNo, 'key')
      if (lastTick !== null && tick < lastTick) {
        throw new LineError(lineNo, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick

      let bestPrefix = null
      let policyNames = null
      for (const [prefix, names] of routes) {
        if (key.startsWith(prefix) && (bestPrefix === null || prefix.length > bestPrefix.length)) {
          bestPrefix = prefix
          policyNames = names
        }
      }

      const s = statsFor(key)
      if (policyNames === null) {
        s.allowed += 1
        totalAllowed += 1
        if (mode === 'replay') out.push(`${tick} ${key} allow`)
        continue
      }

      const involved = policyNames.map((name) => policies.get(name))
      for (const policy of involved) policy.advance(key, tick)

      let denyingPolicy = null
      for (let j = 0; j < involved.length; j += 1) {
        if (!involved[j].allow(key)) {
          denyingPolicy = policyNames[j]
          break
        }
      }

      if (denyingPolicy === null) {
        for (const policy of involved) policy.record(key, tick)
        s.allowed += 1
        totalAllowed += 1
        if (mode === 'replay') out.push(`${tick} ${key} allow`)
      } else {
        s.denied += 1
        totalDenied += 1
        if (mode === 'replay') out.push(`${tick} ${key} deny ${denyingPolicy}`)
      }
    } else {
      throw new LineError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (mode === 'summary') {
    for (const key of [...stats.keys()].sort()) {
      const s = stats.get(key)
      out.push(`${key} allowed=${s.allowed} denied=${s.denied}`)
    }
    out.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

