import fs from 'node:fs'
import { simulate } from './simulate.js'
import { LineError } from './errors.js'

function readStdin() {
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (err) {
    if (err.code === 'EAGAIN') return fs.readFileSync('/dev/stdin', 'utf8')
    throw err
  }
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  try {
    const output = simulate(input, mode)
    process.stdout.write(output)
    process.exit(0)
  } catch (err) {
    if (err instanceof LineError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }
}

main()
